  "inlineSchema": "generator client {\n  provider   = \"prisma-client-js\"\n  output     = \"../src/generated/client\"\n  engineType = \"client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Usuario {\n  id        Int      @id @default(autoincrement())\n  nome      String\n  email     String   @unique\n  senhaHash String?\n  createdAt DateTime @default(now())\n\n  disciplinas   Disciplina[]\n  questoes      Questao[]\n  respostas     Resposta[]\n  flashcards    Flashcard[]\n  movimentacoes Movimentacao[]\n\n  casosCriados  CasoClinico[]\n  investigacoes InvestigacaoCaso[]\n}\n\nmodel Disciplina {\n  id        Int      @id @default(autoincrement())\n  nome      String\n  createdAt DateTime @default(now())\n\n  usuarioId Int\n  usuario   Usuario @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n\n  questoes Questao[]\n}\n\nmodel Questao {\n  id          Int      @id @default(autoincrement())\n  enunciado   String\n  explicacao  String?\n  tema        String?\n  dificuldade String?\n  createdAt   DateTime @default(now())\n\n  usuarioId Int\n  usuario   Usuario @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n\n  disciplinaId Int\n  disciplina   Disciplina @relation(fields: [disciplinaId], references: [id], onDelete: Cascade)\n\n  alternativas Alternativa[]\n  respostas    Resposta[]\n}\n\nmodel Alternativa {\n  id      Int     @id @default(autoincrement())\n  texto   String\n  correta Boolean @default(false)\n\n  questaoId Int\n  questao   Questao @relation(fields: [questaoId], references: [id], onDelete: Cascade)\n}\n\nmodel Resposta {\n  id           Int      @id @default(autoincrement())\n  correta      Boolean\n  respondidaAt DateTime @default(now())\n\n  usuarioId Int\n  usuario   Usuario @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n\n  questaoId Int\n  questao   Questao @relation(fields: [questaoId], references: [id], onDelete: Cascade)\n}\n\nmodel Flashcard {\n  id        Int      @id @default(autoincrement())\n  frente    String\n  verso     String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  usuarioId Int\n  usuario   Usuario @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n}\n\nmodel Movimentacao {\n  id        Int              @id @default(autoincrement())\n  descricao String\n  valor     Decimal          @db.Decimal(10, 2)\n  tipo      TipoMovimentacao\n  data      DateTime         @default(now())\n  createdAt DateTime         @default(now())\n\n  usuarioId Int\n  usuario   Usuario @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n}\n\n/**\n * =========================================================\n * CASOS CLÍNICOS\n * =========================================================\n */\n\nmodel CasoClinico {\n  id Int @id @default(autoincrement())\n\n  titulo        String\n  area          String\n  especialidade String?\n  dificuldade   String\n  cenario       String\n\n  queixaInicial String\n\n  /**\n   * Informações apresentadas automaticamente no início.\n   * Nunca devem conter o diagnóstico final.\n   */\n  dadosIniciais Json\n\n  /**\n   * Informações que o servidor libera\n   * somente quando o usuário solicita.\n   */\n  anamnese Json\n\n  exameFisico Json\n\n  sinaisVitais Json\n\n  /**\n   * Mantido para informações gerais do caso.\n   * Os exames solicitáveis individualmente ficam em ExameCaso.\n   */\n  exames Json\n\n  evolucao Json\n\n  /**\n   * Informações ocultas durante a investigação.\n   */\n  diagnosticoFinal String\n\n  explicacaoDiagnostico String\n\n  diagnosticosDiferenciais Json\n\n  pontosChave Json\n\n  /**\n   * Configurações do caso.\n   */\n  publicado Boolean @default(false)\n\n  geradoPorIA Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  autorId Int\n  autor   Usuario @relation(fields: [autorId], references: [id], onDelete: Cascade)\n\n  investigacoes InvestigacaoCaso[]\n  examesCaso    ExameCaso[]\n\n  @@index([area])\n  @@index([dificuldade])\n  @@index([publicado])\n  @@index([autorId])\n  @@index([geradoPorIA])\n}\n\nmodel ExameCaso {\n  id Int @id @default(autoincrement())\n\n  casoId Int\n  caso   CasoClinico @relation(fields: [casoId], references: [id], onDelete: Cascade)\n\n  /**\n   * Exemplo:\n   * Hemograma\n   * Gasometria arterial\n   * ECG\n   * Radiografia de tórax\n   * Troponina\n   */\n  nome String\n\n  categoria String?\n\n  /**\n   * O que o exame realmente mostrou.\n   * Fica no banco e NÃO é enviado antes de ser solicitado.\n   */\n  resultado String\n\n  interpretacao String?\n\n  /**\n   * Ajuda o sistema a organizar a investigação.\n   */\n  disponivel Boolean @default(true)\n\n  ordem Int @default(0)\n\n  createdAt DateTime @default(now())\n\n  @@index([casoId])\n  @@index([nome])\n}\n\nmodel InvestigacaoCaso {\n  id Int @id @default(autoincrement())\n\n  casoId Int\n  caso   CasoClinico @relation(fields: [casoId], references: [id], onDelete: Cascade)\n\n  usuarioId Int\n  usuario   Usuario @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n\n  /**\n   * EM_ANDAMENTO\n   * FINALIZADA\n   */\n  status String @default(\"EM_ANDAMENTO\")\n\n  /**\n   * Guarda tudo que o aluno já descobriu.\n   */\n  informacoesColetadas Json\n\n  /**\n   * Hipótese diagnóstica enviada pelo aluno.\n   */\n  hipotese String?\n\n  /**\n   * Raciocínio utilizado pelo aluno.\n   */\n  justificativa String?\n\n  /**\n   * Avaliação feita pelo sistema depois\n   * da hipótese final.\n   */\n  avaliacao Json?\n\n  finalizado Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  registros RegistroInvestigacao[]\n\n  @@unique([casoId, usuarioId])\n  @@index([usuarioId])\n  @@index([casoId])\n  @@index([status])\n  @@index([finalizado])\n}\n\nmodel RegistroInvestigacao {\n  id Int @id @default(autoincrement())\n\n  investigacaoId Int\n  investigacao   InvestigacaoCaso @relation(fields: [investigacaoId], references: [id], onDelete: Cascade)\n\n  /**\n   * Exemplos:\n   * ANAMNESE\n   * EXAME_FISICO\n   * SINAL_VITAL\n   * EXAME\n   * EVOLUCAO\n   * HIPOTESE\n   */\n  tipo String\n\n  titulo String\n\n  /**\n   * Pergunta feita pelo usuário.\n   * Exemplo:\n   * \"Quais são os antecedentes do paciente?\"\n   */\n  pergunta String?\n\n  /**\n   * Resposta liberada pelo sistema.\n   */\n  resposta String\n\n  /**\n   * Ordem cronológica da investigação.\n   */\n  ordem Int\n\n  createdAt DateTime @default(now())\n\n  @@index([investigacaoId])\n  @@index([tipo])\n}\n\nenum TipoMovimentacao {\n  RECEITA\n  DESPESA\n}\n",
